import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        print(0)
        return

    it = iter(data)
    try:
        N = int(next(it))
        W = int(next(it))
    except StopIteration:
        print(0)
        return

    values = [int(next(it)) for _ in range(N)]
    weights = [int(next(it)) for _ in range(N)]

    if W <= 0:
        print(0)
        return

    dp = [0] * (W + 1)

    for v, wt in zip(values, weights):
        if wt < 0 or wt > W:
            continue
        for j in range(W, wt - 1, -1):
            cand = dp[j - wt] + v
            if cand > dp[j]:
                dp[j] = cand

    print(dp[W])

if __name__ == "__main__":
    solve()
